CREATE TABLE contest_participation (
    c_id NUMBER NOT NULL,
    c_name varchar(30),
    c_date date,
    c_player1 varchar(30) not null,
    c_player2 varchar(40),
    c_type varchar(40),
    c_location varchar(30),
    c_winner varchar(40),

    CONSTRAINT fk_participation_contest
        FOREIGN KEY (c_id)
        REFERENCES contest(c_id)
);

